import os, glob
import pypdf, docx, openpyxl

def read_pdf(p):
    print('=== PDF:', p)
    reader = pypdf.PdfReader(p)
    for i, page in enumerate(reader.pages):
        print(f'--- Page {i+1} ---')
        print(page.extract_text())

def read_docx(p):
    print('=== DOCX:', p)
    doc = docx.Document(p)
    for para in doc.paragraphs:
        if para.text.strip():
            print(para.text)
    for t in doc.tables:
        print('--- Table ---')
        for row in t.rows:
            print([c.text.strip() for c in row.cells])

def read_xlsx(p):
    print('=== XLSX:', p)
    wb = openpyxl.load_workbook(p, data_only=True)
    for name in wb.sheetnames:
        print('--- Sheet:', name)
        ws = wb[name]
        for row in ws.iter_rows(values_only=True):
            if any(row):
                print(row)

