import re, docx

doc = docx.Document('/app/files/output/CFDME-2025-041_validation_memo_revA.docx')
all_texts = []
for i, p in enumerate(doc.paragraphs):
    if p.text.strip():
        all_texts.append((f'P{i}', p.text))
for ti, t in enumerate(doc.tables):
    for ri, row in enumerate(t.rows):
        for ci, cell in enumerate(row.cells):
            all_texts.append((f'T{ti}R{ri}C{ci}', cell.text))

# Find any standalone numbers not immediately followed by a unit or part of an ID/date/section
for loc, txt in all_texts:
    # Print any matches of numbers to review context
    for m in re.finditer(r'(?<![A-Za-z0-9_#-])\d+(?:\.\d+)?(?![A-Za-z0-9_/-])', txt):
        start = max(0, m.start() - 15)
        end = min(len(txt), m.end() + 25)
        snippet = txt[start:end].replace('\n', ' ')
        print(f'{loc:10s} | {m.group(0):8s} | ...{snippet}...')
